#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    int64_t* data;
    size_t len;
} Arr_i64;

Arr_i64 swapAt(Arr_i64 arr, int64_t num1, int64_t num2) {
    if (arr.len == 0) return arr;
    Arr_i64 result;
    result.len = arr.len;
    result.data = malloc(arr.len * sizeof(int64_t));
    if (result.data == NULL) exit(1);
    for (size_t k = 0; k < arr.len; k++) {
        result.data[k] = arr.data[k];
    }
    result.data[num1] = arr.data[num2];
    result.data[num2] = arr.data[num1];
    return result;
}

void print_arr(Arr_i64 arr) {
    printf("[");
    for (size_t i = 0; i < arr.len; i++) {
        printf("%ld", arr.data[i]);
        if (i < arr.len - 1) printf(";");
    }
    printf("]");
}

int main() {
    Arr_i64 arr1 = { (int64_t[]){1,2,3,4,5}, 5 };
    Arr_i64 arr2 = { (int64_t[]){10}, 1 };
    Arr_i64 arr3 = { NULL, 0 };
    Arr_i64 arr4 = { (int64_t[]){7,8,9}, 3 };
    Arr_i64 arr5 = { (int64_t[]){100,200,300,400}, 4 };

    Arr_i64 r1 = swapAt(arr1, 0, 4);
    Arr_i64 r2 = swapAt(arr2, 0, 0);
    Arr_i64 r3 = swapAt(arr3, 0, 0);
    Arr_i64 r4 = swapAt(arr4, 1, 2);
    Arr_i64 r5 = swapAt(arr5, 0, 3);

    print_arr(r1); printf("\n");
    print_arr(r2); printf("\n");
    print_arr(r3); printf("\n");
    print_arr(r4); printf("\n");
    print_arr(r5); printf("\n");

    free(r1.data);
    free(r2.data);
    free(r3.data);
    free(r4.data);
    free(r5.data);
    return 0;
}

