import java.util.Arrays;

public class Solution {
    public static int[] swapAt(int[] arr, int i, int j) {
        if (arr == null || arr.length == 0) {
            return new int[0];
        }
        int[] result = Arrays.copyOf(arr, arr.length);
        int temp = result[i];
        result[i] = result[j];
        result[j] = temp;
        return result;
    }

    public static void main(String[] args) {
        // Test 1: Normal case
        int[] arr1 = {1, 2, 3, 4, 5};
        int[] res1 = swapAt(arr1, 1, 3);
        System.out.println(Arrays.toString(res1));

        // Test 2: Swap first and last
        int[] arr2 = {10, 20, 30, 40, 50};
        int[] res2 = swapAt(arr2, 0, 4);
        System.out.println(Arrays.toString(res2));

        // Test 3: Empty array
        int[] arr3 = {};
        int[] res3 = swapAt(arr3, 0, 0);
        System.out.println(Arrays.toString(res3));

        // Test 4: Single element array
        int[] arr4 = {42};
        int[] res4 = swapAt(arr4, 0, 0);
        System.out.println(Arrays.toString(res4));

        // Test 5: Swap adjacent elements
        int[] arr5 = {5, 6, 7, 8};
        int[] res5 = swapAt(arr5, 1, 2);
        System.out.println(Arrays.toString(res5));
    }
}
